import {chromium,devices,expect} from '@playwright/test';
import {readFileSync,mkdirSync,writeFileSync} from 'node:fs';
const origin='https://thu-phong-private.pages.dev',dir='.dsh-tmp/tts-continuous-production';mkdirSync(dir,{recursive:true});
const html=(await(await fetch(origin)).text()).trim();expect(html).toBe(readFileSync('dist/index.html','utf8').trim());
const data=readFileSync('tests/fixtures/tts-continuous.mp3').toString('base64');
const browser=await chromium.launch({channel:'msedge'}),context=await browser.newContext({...devices['Pixel 7'],serviceWorkers:'block'});let offline=false;
try{
 await context.route(origin+'/api/**',r=>r.fulfill({status:503}));
 await context.route(origin+'/api/ai/translate',r=>{const input=r.request().postDataJSON();return r.fulfill({json:{result:input.text,model:input.model,finishReason:'STOP',inputTokens:1,outputTokens:1}});});
 await context.route('https://ottsy.weilbyte.dev/api/generation',r=>offline?r.abort('internetdisconnected'):r.fulfill({json:{success:true,data}}));
 await context.addInitScript(()=>{const NativeAudio=window.Audio;window.__audios=[];window.__handlers={};window.Audio=function(){const a=new NativeAudio();window.__audios.push(a);return a;};const original=navigator.mediaSession.setActionHandler.bind(navigator.mediaSession);navigator.mediaSession.setActionHandler=(name,handler)=>{window.__handlers[name]=handler;original(name,handler);};});
 const page=await context.newPage(),requests=[];page.on('request',r=>requests.push(r.url()));page.setDefaultTimeout(30000);await page.goto(origin,{waitUntil:'domcontentloaded'});
 await page.getByRole('button',{name:/Thêm truyện TXT/}).click();await page.getByLabel('Tên truyện',{exact:true}).fill('Kiểm tra luồng nghe liên tục');await page.getByLabel('Hoặc dán nội dung',{exact:true}).fill('Chương 1\n'+Array.from({length:20},(_,i)=>`Câu thử số ${i} để kiểm tra âm thanh liên tục.`).join('\n'));await page.getByRole('button',{name:'Nhập truyện',exact:true}).click();
 await expect(page.locator('.reader-book-heading h1')).toHaveText('Kiểm tra luồng nghe liên tục');await page.waitForURL('**/read/*/*');const bookId=page.url().split('/')[4],listen=page.getByRole('button',{name:'Nghe truyện nhanh',exact:true});
 const dismiss=async()=>{const close=page.getByRole('button',{name:'Đóng thông báo',exact:true});if(await close.isVisible())await close.click();};
 const cursor=()=>page.evaluate(id=>JSON.parse(localStorage.getItem('tts-cursor:v1:'+id)),bookId);
 const audio=()=>page.evaluate(()=>{const a=window.__audios[0];return {time:a.currentTime,src:a.getAttribute('src'),paused:a.paused,rate:a.playbackRate,count:window.__audios.length};});
 const source=()=>page.evaluate(async()=>{const database=await new Promise((resolve,reject)=>{const r=indexedDB.open('thu-phong-v1');r.onsuccess=()=>resolve(r.result);r.onerror=()=>reject(r.error);});try{return await new Promise((resolve,reject)=>{const tx=database.transaction('chapters','readonly'),r=tx.objectStore('chapters').getAll();tx.oncomplete=()=>resolve(r.result.map(c=>({id:c.id,revision:c.revision,text:c.text})));tx.onerror=()=>reject(tx.error);});}finally{database.close();}});
 await dismiss();await page.getByRole('button',{name:'Cài đặt đọc truyện',exact:true}).click();await page.getByRole('button',{name:'▶ Nghe sách',exact:true}).click();await page.getByRole('slider',{name:'Tốc độ đọc',exact:true}).fill('5');await page.getByRole('button',{name:'Ẩn Nghe sách',exact:true}).click();
 const original=await source();await listen.click();await expect(listen).toHaveAttribute('title','Tạm dừng nghe');const initial=await audio();expect(initial).toMatchObject({rate:5,count:1});await expect.poll(async()=>(await cursor())?.offset??-1).toBeGreaterThan(0);expect((await audio()).src).toBe(initial.src);
 await page.evaluate(()=>window.__handlers.pause());await expect(listen).toHaveAttribute('title','Tiếp tục nghe');const paused=await cursor();await page.evaluate(()=>window.__handlers.play());await expect(listen).toHaveAttribute('title','Tạm dừng nghe');expect((await cursor()).offset).toBeGreaterThanOrEqual(paused.offset);
 offline=true;await expect(listen).toHaveAttribute('title','Tiếp tục nghe',{timeout:25000});const failed=await cursor();expect(failed.offset).toBeGreaterThan(0);offline=false;await dismiss();await listen.click();await expect(listen).toHaveAttribute('title','Tạm dừng nghe');expect((await cursor()).offset).toBeGreaterThanOrEqual(failed.offset);expect((await audio()).src).toBe(initial.src);expect((await audio()).count).toBe(1);
 await page.evaluate(()=>window.__handlers.pause());await page.getByRole('button',{name:'Cài đặt đọc truyện',exact:true}).click();await page.getByRole('button',{name:'▶ Nghe sách',exact:true}).click();await expect(page.getByRole('checkbox',{name:'Giữ phiên nghe nền (thử nghiệm)',exact:true})).toHaveCount(0);await page.screenshot({path:dir+'/panel.png'});
 await page.reload({waitUntil:'domcontentloaded'});await expect(listen).toHaveAttribute('data-resume','true');expect(await page.evaluate(()=>window.__audios.length)).toBe(0);await dismiss();await listen.click();await expect(listen).toHaveAttribute('title','Tạm dừng nghe');expect(await source()).toEqual(original);
 await page.getByRole('button',{name:'Dừng đọc nhanh',exact:true}).click();expect(await cursor()).toBeNull();expect((await audio()).src).toBeNull();expect(requests.some(url=>url.includes('tts-media-keepalive'))).toBe(false);
 const report={status:'passed',synthetic:true,nativeMp3Mse:true,mockedGateway:true,cloudWrites:false,androidLayout:true,realAndroidLock:false,singleAudio:true,sameSourceAcrossChunksAndRetry:true,relativeCursor:true,reloadNoAutoplay:true,stopRelease:true,noSilentAssetRequest:true,sourceUnchanged:true,bundle:html.match(/src="([^"]+\.js)"/)[1]};writeFileSync(dir+'/report.json',JSON.stringify(report,null,2));console.log(JSON.stringify(report));
}finally{await context.close();await browser.close();}
